256	#define XDP_TXMD_FLAGS_VALID ( \
257			XDP_TXMD_FLAGS_TIMESTAMP | \
258			XDP_TXMD_FLAGS_CHECKSUM | \
259			XDP_TXMD_FLAGS_LAUNCH_TIME | \
260		0)
261	
262	static inline bool
263	xsk_buff_valid_tx_metadata(const struct xsk_buff_pool *pool,
264				   const struct xsk_tx_metadata *meta, u64 *flags)
265	{
266		*flags = READ_ONCE(meta->flags);
267		if (*flags & XDP_TXMD_FLAGS_LAUNCH_TIME)
268			if (pool->tx_metadata_len <
269			    offsetofend(struct xsk_tx_metadata, request.launch_time))
270				return false;
271		return !(*flags & ~XDP_TXMD_FLAGS_VALID);
272	}
273	
274	/**
275	 *  xsk_tx_metadata_request - Evaluate AF_XDP TX metadata at submission
276	 *  and call appropriate xsk_tx_metadata_ops operation.
277	 *  @pmeta: pointer to pointer to AF_XDP metadata area
278	 *  @ops: pointer to struct xsk_tx_metadata_ops
279	 *  @priv: pointer to driver-private aread
280	 *
281	 *  This function should be called by the networking device when
282	 *  it prepares AF_XDP egress packet.
283	 */
284	static inline void xsk_tx_metadata_request(struct xsk_tx_metadata **pmeta,
285						   const struct xsk_tx_metadata_ops *ops,
286						   void *priv)
287	{
288		const struct xsk_tx_metadata *meta = *pmeta;
289	
290		if (!meta)
291			return;
292	
293		if (ops->tmo_request_launch_time)
294			if (meta->flags & XDP_TXMD_FLAGS_LAUNCH_TIME)
295				ops->tmo_request_launch_time(meta->request.launch_time,
296							     priv);
297	
298		if (ops->tmo_request_timestamp)
299			if (meta->flags & XDP_TXMD_FLAGS_TIMESTAMP)
300				ops->tmo_request_timestamp(priv);
301	
302		if (ops->tmo_request_checksum)
303			if (meta->flags & XDP_TXMD_FLAGS_CHECKSUM)
304				ops->tmo_request_checksum(meta->request.csum_start,
305							  meta->request.csum_offset, priv);
306	
307		if (!(meta->flags & XDP_TXMD_FLAGS_TIMESTAMP))
308			*pmeta = NULL;
309	}
