311	static inline struct xsk_tx_metadata *
312	__xsk_buff_get_metadata(const struct xsk_buff_pool *pool, void *data)
313	{
314		struct xsk_tx_metadata *meta;
315		u64 flags;
316	
317		if (!pool->tx_metadata_len)
318			return NULL;
319	
320		meta = data - pool->tx_metadata_len;
321		if (unlikely(!xsk_buff_valid_tx_metadata(pool, meta, &flags)))
322			return NULL; /* no way to signal the error to the user */
323	
324		return meta;
325	}
