500	void xsk_tx_completed(struct xsk_buff_pool *pool, u32 nb_entries)
501	{
502		u32 reclaim_descs = READ_ONCE(pool->reclaim_descs);
503	
504		if (unlikely(reclaim_descs)) {
505			u32 pending_descs = READ_ONCE(pool->tx_zc_pending_descs);
506	
507			if (nb_entries < pending_descs) {
508				WRITE_ONCE(pool->tx_zc_pending_descs,
509					   pending_descs - nb_entries);
510				xskq_prod_submit_n(pool->cq, nb_entries);
511				return;
512			}
513	
514			WRITE_ONCE(pool->tx_zc_pending_descs, 0);
515			nb_entries += reclaim_descs;
516			WRITE_ONCE(pool->reclaim_descs, 0);
517		}
518	
519		xskq_prod_submit_n(pool->cq, nb_entries);
520	}
